/**
 * Markdown for producer-supplied text. Producers are untrusted, so output is restricted at
 * render time: raw HTML is shown as text, images are replaced by their alt text (nothing loads
 * remotely), and links keep only http, https and mailto targets. Everything else marked emits is
 * generated by marked from escaped text.
 */
import { Marked } from 'marked';

const escapeHtml = (text: string): string =>
  text
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');

const SAFE_PROTOCOLS = new Set(['http:', 'https:', 'mailto:']);

/** Returns the href when it is an absolute http, https or mailto URL, otherwise null. */
export function safeHref(href: string | null | undefined): string | null {
  if (!href) return null;
  try {
    const url = new URL(href.trim());
    return SAFE_PROTOCOLS.has(url.protocol) ? url.href : null;
  } catch {
    return null;
  }
}

const marked = new Marked({
  gfm: true,
  async: false,
  renderer: {
    html({ text }) {
      return escapeHtml(text);
    },
    image({ text }) {
      return escapeHtml(text);
    },
    link({ href, tokens }) {
      const inner = this.parser.parseInline(tokens);
      const safe = safeHref(href);
      return safe ? `<a href="${escapeHtml(safe)}" rel="noopener noreferrer" target="_blank">${inner}</a>` : inner;
    }
  }
});

/** Renders markdown to an HTML string that is safe to use with `{@html}`. */
export function renderMarkdown(source: string): string {
  return marked.parse(source) as string;
}
